const r = $json;
let row = {};
try { row = $('Montar consulta').item.json; } catch (e) { row = {}; }

const status = (r.status != null ? r.status : (r.data && r.data.status)) || '';
const externalStatus = r.external_status || r.data?.external_status || '';

// DEFINIÇÃO CORRETA DE STATUS FINAIS (Acionáveis)
const APPROVED_FINAL = ['approved'];
const DENIED_FINAL   = ['denied', 'fails_to_process', 'lost', 'cancelled'];
const FORMALIZATION  = ['formalization'];
const WON_FINAL      = ['won'];
const FAIL_CONTACT   = ['fail_to_contact'];

let outcome = 'pending';

// Verifica se existe conteúdo real no offer_data
const offerData = r.offer_data || r.data?.offer_data || null;
const hasOfferData = offerData && Object.keys(offerData).length > 0;

// Lógica de Classificação Baseada no Status (Não apenas no offer_data)
if (APPROVED_FINAL.includes(status) && hasOfferData) {
    outcome = 'offer';
} else if (DENIED_FINAL.includes(status)) {
    outcome = 'rejected';
} else if (FORMALIZATION.includes(status)) {
    outcome = 'formalization';
} else if (FAIL_CONTACT.includes(status)) {
    outcome = 'fail_to_contact';
} else if (WON_FINAL.includes(status)) {
    outcome = 'won';
} else {
    // Para 'comite_approved', 'comite', 'in_quoting', 'in_progress', etc.
    // Permanece 'pending' para que o Poller continue monitorando a cada minuto
    // até atingir um status acionável.
    outcome = 'pending';
}

const decided = outcome !== 'pending';

// Detecta se algo mudou em relação ao que está no banco
const currentStatus   = row._current_status   || '';
const currentExternal = row._current_external || '';
const status_changed  = decided ||
                        (status !== currentStatus) ||
                        (externalStatus !== currentExternal);

const name = row._contact_name || 'Parceiro';

// Monta mensagem apenas se DECIDIDO
let message = '';

if (outcome === 'offer') {
  const amount = offerData?.SomaPrincipal || r.data?.amount || '';
  const term   = offerData?.installments  || r.data?.installments || '';
  const tax    = offerData?.PercJurosMensal || '';
  const amountFmt = amount ? Number(amount).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}) : '';
  const reqAmount = parseFloat(row._requested_amount || 0);
  const maxApproved = parseFloat(amount || 0);
  const maxTerm = term || 24;

  let ctaMessage = `👉 *Quer simular agora?* Me diga o valor que precisa e em quantas parcelas (de 6 a ${maxTerm} parcelas)!`;
  if (reqAmount > 0) {
    if (maxApproved > 0 && reqAmount > maxApproved) {
      ctaMessage = `O valor de *R$ ${reqAmount.toLocaleString('pt-BR')}* que você solicitou excede o seu limite pré-aprovado de *R$ ${amountFmt}*.\n\n👉 *Por favor, informe qual valor deseja solicitar (até R$ ${amountFmt}) e em quantas parcelas (de 6 a ${maxTerm} parcelas)!*`;
    } else {
      ctaMessage = `Entendi que você deseja simular o valor de *R$ ${reqAmount.toLocaleString('pt-BR')}*.\n\n👉 *Em quantas parcelas você gostaria de simular? (Lembrando que o prazo é de 6 a ${maxTerm} parcelas).*`;
    }
  }

  message = `🎉 *Boa notícia, ${name}!*\n\n` +
    `A análise do seu CNPJ foi concluída e você tem crédito pré-aprovado!\n\n` +
    (amountFmt ? `💰 *Limite aprovado:* R$ ${amountFmt}\n` : '') +
    (term  ? `📅 *Prazo:* até ${term} parcelas\n` : '') +
    (tax   ? `📉 *Taxa:* a partir de ${tax}% a.m.\n\n` : '') +
    `✅ Pagamento via *Boleto Bancário* mensal\n` +
    `✅ Garantia via recebíveis Ticket\n\n` +
    `Você pode simular diferentes valores e prazos (de 6 a ${maxTerm} meses) dentro do seu limite aprovado.\n\n` +
    ctaMessage;

} else if (outcome === 'rejected') {
  const motivo = externalStatus || (status === 'cancelled' ? 'cancelamento da solicitação' :
                                    status === 'lost'      ? 'encerramento da proposta' : 
                                    'políticas internas de crédito');

  message = `Olá, *${name}*!\n\n` +
    `*${motivo}*.\n\n` +
    `Isso não é definitivo! Você pode tentar novamente em *30 dias*.\n\n` +
    `Central de Atendimento: *4004-2233*\n\n` +
    `Obrigado pela confiança na Ticket! 🙏`;

} else if (outcome === 'fail_to_contact') {
  message = `Olá, *${name}*!\n\n` +
    `A nossa mesa de crédito tentou entrar em contato com você por telefone para prosseguir com a análise, mas infelizmente não conseguiu. 😕\n\n` +
    `👉 *Qual é o melhor telefone e horário para nossa equipe te ligar?*`;

} else if (outcome === 'formalization') {
  message = `Olá, *${name}*! Excelente notícia!\n\n` +
    `Sua proposta de crédito foi *100% aprovada* e está agora na fase final de Assinatura e Formalização! 🎉\n\n` +
    `Fique de olho no seu e-mail e nos seus canais de contato para assinar o contrato digital. Qualquer dúvida, é só chamar!`;

} else if (outcome === 'won') {
  message = `Parabéns, *${name}*! 🚀\n\n` +
    `Seu crédito foi liberado com sucesso e o dinheiro já deve estar disponível na sua conta!\n\n` +
    `Agradecemos por escolher a Ticket e a Fiserv para turbinar o seu negócio. Caso precise de mais alguma coisa no futuro, é só me chamar aqui!`;
}

return {
  _row_id:       row._row_id,
  _tenant_id:    row._tenant_id,
  _phone:        row._phone,
  _campaign_id:  row._campaign_id,
  _contact_name: name,
  cnpj:          row.cnpj,
  loan_request_id: (r.loan_request_id != null ? r.loan_request_id : row.loan_request_id),
  fiserv_ok:     r.ok,
  fiserv_http:   r.http_status,
  status:        status,
  external_status: externalStatus,
  offer_data:    offerData,
  outcome:       outcome,
  decided:       decided,
  status_changed: status_changed,
  message_content: message
};
